pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(bytes memory encodedParameters, address ownedBy) internal {
        vm.assume(true);
        bool wasOperator;
        try c.programOperators(address(this)) returns (bool __r) { wasOperator = __r; } catch { return; }
        bool didRevert;
        address cloneAddr;
        try c.create(encodedParameters, ownedBy) {
            didRevert = false;
            // if it succeeded, read returned clone via another call: create returns address but try-without-return cannot capture it; instead read last emitted RoundCreated? Not available. However create returns the clone address, but try c.create(...) { } does not capture return. To observe success we only need didRevert == false.
        } catch {
            didRevert = true;
        }
        assertTrue(didRevert || wasOperator);
    }

    function testFuzz_run(bytes memory encodedParameters, address ownedBy) public {
        vm.assume(ownedBy.code.length == 0 && uint160(ownedBy) > 0xffff && ownedBy != address(this) && ownedBy != address(c) && ownedBy != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && ownedBy != 0x000000000000000000636F6e736F6c652e6c6f67 && ownedBy != 0x4e59b44847b379578588920cA78FbF26c0B4956C && ownedBy != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(encodedParameters, ownedBy);
    }

    receive() external payable {}
}
